draw:
var r = p.radius, w = p.omega, al = p.alpha;
var v = w * r, ac = w * w * r, at = al * r;
var atot = Math.sqrt(ac * ac + at * at);
var phi = Math.atan2(ac, at) * 180 / Math.PI;

var R = Math.min(W * 0.22, H * 0.33);
var cx = W * 0.34, cy = H * 0.55;
var th = 0.35 * t + 0.9;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.beginPath();
ctx.arc(cx, cy, 3, 0, Math.PI * 2);
ctx.fill();

var px = cx + R * Math.cos(th), py = cy - R * Math.sin(th);

ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(px, py);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("r = " + r.toFixed(2) + " m", cx + R * 0.35 * Math.cos(th) + 4,
  cy - R * 0.35 * Math.sin(th) - 5);

var ux = -Math.sin(th), uy = -Math.cos(th);
var nx = -Math.cos(th), ny = Math.sin(th);

var vs = Math.min(R * 0.9 / Math.max(v, 0.001), 60);
var as = Math.min(R * 1.05 / Math.max(atot, 0.001), 60);

function arrow(x0, y0, dx, dy, col, lab) {
  var L = Math.sqrt(dx * dx + dy * dy);
  if (L < 1) return;
  var ex = dx / L, ey = dy / L;
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x0 + dx, y0 + dy);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0 + dx, y0 + dy);
  ctx.lineTo(x0 + dx - ex * 8 - ey * 4.5, y0 + dy - ey * 8 + ex * 4.5);
  ctx.lineTo(x0 + dx - ex * 8 + ey * 4.5, y0 + dy - ey * 8 - ex * 4.5);
  ctx.closePath();
  ctx.fill();
  ctx.fillText(lab, x0 + dx + ex * 6 - 4, y0 + dy + ey * 6 + 4);
}

arrow(px, py, ux * v * vs, uy * v * vs, C.accent, "v = " + v.toFixed(2) + " m/s");
arrow(px, py, nx * ac * as, ny * ac * as, C.figure, "a_c = " + ac.toFixed(1));
arrow(px, py, ux * at * as, uy * at * as, C.figure, "a_t = " + at.toFixed(1));

ctx.setLineDash([2, 3]);
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(px + ux * at * as, py + uy * at * as);
ctx.lineTo(px + ux * at * as + nx * ac * as, py + uy * at * as + ny * ac * as);
ctx.moveTo(px + nx * ac * as, py + ny * ac * as);
ctx.lineTo(px + ux * at * as + nx * ac * as, py + uy * at * as + ny * ac * as);
ctx.stroke();
ctx.setLineDash([]);

arrow(px, py, (ux * at + nx * ac) * as, (uy * at + ny * ac) * as, C.ink,
  "a = " + atot.toFixed(1) + " m/s^2");

var bx = W * 0.68;
var by = H * 0.20;
var lh = Math.min(20, H * 0.12);
ctx.fillStyle = C.ink;
ctx.fillText("v   = omega r  = " + v.toFixed(2) + " m/s", bx, by);
ctx.fillText("a_t = alpha r  = " + at.toFixed(2), bx, by + lh);
ctx.fillText("a_c = omega^2 r = " + ac.toFixed(2), bx, by + 2 * lh);
ctx.fillStyle = C.accent;
ctx.fillText("angle(a, v) = " + phi.toFixed(1) + " deg", bx, by + 3 * lh);

out.note = "|a| = " + atot.toFixed(2) + " m/s^2, tilted " + phi.toFixed(1) +
  " deg from the velocity (tan = a_c / a_t = " + (ac / Math.max(at, 1e-9)).toFixed(2) + ")";
